WHENEVER SQLERROR EXIT FAILURE ROLLBACK
BEGIN
 EXECUTE IMMEDIATE 'CREATE TABLE DAC_EDS_DATA (LOT_ID VARCHAR2(40),WAFER_ID VARCHAR2(40),PRODUCT VARCHAR2(40) NOT NULL,TESTED_DIES NUMBER(8) NOT NULL,GOOD_DIES NUMBER(8) NOT NULL,YIELD_PCT NUMBER(6,2) NOT NULL,CONSTRAINT DAC_EDS_PK PRIMARY KEY(LOT_ID,WAFER_ID),CONSTRAINT DAC_EDS_YIELD CHECK(YIELD_PCT BETWEEN 0 AND 100))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN
 EXECUTE IMMEDIATE 'CREATE TABLE DAC_DEFECT_DATA (DEFECT_ID VARCHAR2(40) PRIMARY KEY,LOT_ID VARCHAR2(40) NOT NULL,WAFER_ID VARCHAR2(40) NOT NULL,DEFECT_TYPE VARCHAR2(40) NOT NULL,SEVERITY VARCHAR2(10) NOT NULL,DEFECT_COUNT NUMBER(8) NOT NULL,CONSTRAINT DAC_DEFECT_SEVERITY CHECK(SEVERITY IN (''LOW'',''MEDIUM'',''HIGH'',''CRITICAL'')))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN
